#include <cstdio>
#ifndef HBC_ROOT
#define HBC_ROOT "/home/imo/HeCBench_julia/src/hbc-julia"
#endif
struct HCase{int n,m;std::vector<int>R,C,F;std::vector<double>bc,budget;};
inline std::vector<HCase>hload(){std::ifstream f(std::string(HBC_ROOT)+"/fixtures.bin",std::ios::binary),o(std::string(HBC_ROOT)+"/oracle.bin",std::ios::binary);auto read=[&](){int v;if(!f.read((char*)&v,4))throw std::runtime_error("fixture bounds");return v;};int nc=read();std::vector<HCase>cs;for(int k=0;k<nc;k++){HCase c;c.n=read();c.m=read();for(int i=0;i<=c.n;i++)c.R.push_back(read());for(int i=0;i<2*c.m;i++)c.C.push_back(read());for(int i=0;i<2*c.m;i++)c.F.push_back(read());int n;o.read((char*)&n,4);if(n!=c.n)throw std::runtime_error("oracle dimensions");for(int i=0;i<n;i++){double v,b;if(!o.read((char*)&v,8)||!o.read((char*)&b,8))throw std::runtime_error("oracle bounds");c.bc.push_back(v);c.budget.push_back(b);}cs.push_back(c);}return cs;}
struct HRow{std::vector<int>d;std::vector<uint64_t>sigma;std::vector<long double>delta,error;std::vector<int>counts;int depth;};
inline const HRow&row_oracle(int ci,int source){static auto cs=hload();static std::map<std::pair<int,int>,HRow>cache;auto key=std::make_pair(ci,source);auto found=cache.find(key);if(found!=cache.end())return found->second;auto&c=cs[ci];HRow r;r.d.assign(c.n,INT_MAX);r.sigma.assign(c.n,0);r.delta.assign(c.n,0);r.error.assign(c.n,0);r.depth=0;std::vector<int>q={source};r.d[source]=0;r.sigma[source]=1;for(size_t i=0;i<q.size();i++){int u=q[i];r.depth=std::max(r.depth,r.d[u]);for(int j=c.R[u];j<c.R[u+1];j++){int v=c.C[j];if(r.d[v]==INT_MAX){r.d[v]=r.d[u]+1;q.push_back(v);}if(r.d[v]==r.d[u]+1){auto z=(unsigned __int128)r.sigma[v]+r.sigma[u];if(z>UINT64_MAX)throw std::runtime_error("oracle path overflow");r.sigma[v]=z;}}}r.counts.assign(r.depth+1,0);for(int v:q)r.counts[r.d[v]]++;long double unit=std::ldexp((long double)1,-24),factor=std::pow(1+unit,4)/(1-unit);for(int i=int(q.size())-1;i>=0;i--){int u=q[i];if(u==source)continue;long double sum=0,err=0;int terms=0;for(int j=c.R[u];j<c.R[u+1];j++){int v=c.C[j];if(r.d[v]==r.d[u]+1){long double ratio=(long double)r.sigma[u]/r.sigma[v],term=ratio*(1+r.delta[v]);sum+=term;err+=factor*ratio*(1+r.delta[v]+r.error[v])-term;terms++;}}r.delta[u]=sum;long double g=terms*unit/(1-terms*unit);r.error[u]=err+g*(sum+err);}return cache.emplace(key,std::move(r)).first->second;}
inline bool check_bc(int ci,const float*raw,double&maxabs,double&maxrel){static auto cs=hload();auto&c=cs[ci];bool ok=true;for(int v=0;v<c.n;v++){double actual=double(raw[v]*.5f),expected=c.bc[v],err=std::abs(actual-expected);maxabs=std::max(maxabs,err);if(expected!=0)maxrel=std::max(maxrel,err/std::abs(expected));bool exact=ci==0||ci==2||expected==0;bool pass=std::isfinite(actual)&&(exact?actual==expected:err<=c.budget[v]+1e-9);if(!pass){fprintf(stderr,"BCcase%d node%d got%.12g expected%.12g error%.9g budget%.9g\n",ci,v,actual,expected,err,c.budget[v]);ok=false;}}return ok;}
inline bool check_rows(int ci,int blocks,const int*d,size_t pd,const uint64_t*sigma,size_t ps,const float*delta,size_t pde,const int*Q,size_t pq,const int*Q2,size_t pq2,const int*S,size_t pst,const int*ep,size_t pe,const int*diam,int next,int jia){static auto cs=hload();auto&c=cs[ci];bool ok=next==80+c.n&&(jia==0||jia==1);for(int block=0;block<blocks;block++){int source=-1;for(int v=0;v<c.n;v++)if(d[block*pd+v]==0){if(source>=0)return false;source=v;}if(source<0){if(block<c.n)return false;continue;}auto&r=row_oracle(ci,source);for(int v=0;v<c.n;v++){if(d[block*pd+v]!=r.d[v]||sigma[block*ps+v]!=r.sigma[v]){fprintf(stderr,"rowcase%d block%d src%d v%d distance/path mismatch\n",ci,block,source,v);return false;}double actual=delta[block*pde+v];if(!std::isfinite(actual)||std::abs((long double)actual-r.delta[v])>r.error[v]+1e-9){fprintf(stderr,"rowcase%d block%d src%d v%d delta%.9g expected%.12Lg budget%.12Lg\n",ci,block,source,v,actual,r.delta[v],r.error[v]);return false;}}int reachable=0;for(int count:r.counts)reachable+=count;std::set<int>seen;for(int k=0;k<reachable;k++){int v=S[block*pst+k];if(v<0||v>=c.n||r.d[v]==INT_MAX||!seen.insert(v).second)return false;}int cumulative=0;for(int depth=0;depth<=r.depth;depth++){if(ep[block*pe+depth]!=cumulative)return false;for(int k=0;k<r.counts[depth];k++)if(r.d[S[block*pst+cumulative+k]]!=depth)return false;cumulative+=r.counts[depth];}if(ep[block*pe+r.depth+1]!=reachable)return false;std::vector<int>frontier;for(int v=0;v<c.n;v++)if(r.d[v]==r.depth)frontier.push_back(v);std::vector<int>q(Q+block*pq,Q+block*pq+frontier.size()),q2(Q2+block*pq2,Q2+block*pq2+frontier.size());std::sort(q.begin(),q.end());std::sort(q2.begin(),q2.end());if(q!=frontier||q2!=frontier)return false;}
// Telemetry source permits INT_MAX overwrite from source0 initialization; record actual schedule, do not force optimization choice.
for(int i=0;i<512;i++){int expected=i<c.n?row_oracle(ci,i).depth:INT_MAX;if(diam[i]!=expected&&diam[i]!=INT_MAX){fprintf(stderr,"diametercase%d index%d value%d expected%d orINT_MAX\n",ci,i,diam[i],expected);ok=false;}}return ok;}
